Review Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Review Service", "Review Service") {
    Component("Review API Router", "Review API Router", "Python / FastAPI Router", "Handles incoming HTTP/REST requests and routing for review submission and retrieval.")
    Component("Review Controller", "Review Controller", "Python / FastAPI", "Orchestrates review business logic, validation, and JWT verification handling.")
    Component("Review Repository", "Review Repository", "SQLAlchemy ORM", "Manages data access and persistence operations for book reviews in Amazon Aurora PostgreSQL.")
}

System_Ext("Amazon Aurora PostgreSQL", "Amazon Aurora PostgreSQL", "Relational database for storing book reviews.")

Rel("Review API Router", "Review Controller", "Routes requests to")
Rel("Review Controller", "Review Repository", "Invokes data persistence operations")
Rel("Review Repository", "Amazon Aurora PostgreSQL", "Reads and writes review data", "TCP with mTLS")

@enduml

Amazon Aurora PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_aurora_postgresql, "Amazon Aurora PostgreSQL") {
    Component(Catalogue_Data_Manager, "Catalogue Data Manager", "PostgreSQL Schema / SQL", "Manages persistent storage and retrieval for the book catalogue data.")
    Component(Order_Data_Manager, "Order Data Manager", "PostgreSQL Schema / SQL", "Handles relational data persistence for transactional orders and checkout safety.")
    Component(Review_Data_Manager, "Review Data Manager", "PostgreSQL Schema / SQL", "Manages relational persistence for user book reviews and ratings.")
    Component(Admin_Data_Manager, "Admin Data Manager", "PostgreSQL Schema / SQL", "Stores administrative configurations, catalogue management data, and system settings.")
}

Rel(Catalogue_Data_Manager, Order_Data_Manager, "Maintains relational consistency for order items and catalogue references")
@enduml

Amazon DynamoDB.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(order_service, "Order and Checkout Service", "Go-based backend service handling customer orders and checkouts.")

Container_Boundary(dynamodb, "Amazon DynamoDB") {
    Component(cart_table, "Cart Table", "Amazon DynamoDB Global Table", "Low-latency data store for managing user shopping carts across multiple regions with TTL and KMS encryption.")
    Component(session_table, "Session Table", "Amazon DynamoDB Global Table", "Low-latency data store for managing active user sessions across multiple regions.")
}

Rel(order_service, cart_table, "Reads and writes shopping cart data", "TLS 1.3 with VPC Endpoints")
Rel(order_service, session_table, "Reads and writes session data", "TLS 1.3 with VPC Endpoints")

@enduml

Amazon OpenSearch.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_opensearch, "Amazon OpenSearch") {
    Component(Search_Index_Engine, "Search Index Engine", "Amazon OpenSearch Engine", "Delivers sub-second full-text and faceted search capabilities.")
    Component(Ingestion_Indexing_Pipeline, "Ingestion & Indexing Pipeline", "Logstash / OpenSearch Ingestion", "Handles data ingestion and indexing pipelines for catalogue and search updates.")
    Component(Cluster_Management_Security, "Cluster Management & Security", "AWS IAM & OpenSearch Security", "Manages cluster scaling, node orchestration, and access security with SigV4.")
}

Rel(Ingestion_Indexing_Pipeline, Search_Index_Engine, "Indexes documents into")
Rel(Cluster_Management_Security, Search_Index_Engine, "Secures and manages cluster nodes for")
@enduml
